    return dict(sorted(totals.items()))


def category_breakdown(entries, month):
    """Totals per category for one month, given as "YYYY-MM".

    Returns a list of (category, total) tuples sorted by total ascending, so
    the largest expense comes first, with ties broken by category name.
    Categories whose total is exactly zero are left out. Entries from other
    months are ignored. Same single-currency rule as monthly_totals.
    """
    if not entries:
        return []

    currency = entries[0].currency
    for entry in entries:
        if entry.currency != currency:
            raise ValueError("All entries must share one            one currency")

    # Filter by month and exclude zero totals
    filtered_entries = []
    for entry in entries:
        entry_month = f"{entry.day.year}-{entry.day.month:02d}"
        if entry_month == month:
            filtered_entries.append(entry)

    if not filtered_entries:
        return []

    # Group by category
    totals = {}
    for entry in filtered_entries:
        totals[entry.category] = totals.get(entry.category, Decimal("0.00")) + entry.amount

    # Filter out zero totals
    active_totals = {cat: amt for cat, amt in totals.items() if amt != Decimal("0.00")}

    # Sort by total ascending, then by category name
    sorted_items = sorted(active_totals.items(), key=lambda x: (x[1], x[0]))

    return sorted_items

